import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const catalogue = JSON.parse(fs.readFileSync(path.join(root, 'data', 'universities.json'), 'utf8'));
const quote = value => value == null ? 'NULL' : `'${String(value).replaceAll("'", "''")}'`;
const lines = [
  '-- Generated by scripts/build-d1-seed.mjs from data/universities.json.',
  '-- Stored review dates are historical V78 metadata, not a current admissions audit.',
  'BEGIN TRANSACTION;'
];

for (const row of catalogue.records) {
  lines.push(`INSERT INTO universities (
  id, name, country, official_url, programs_json, source_label,
  record_status, stored_review_date, updated_at
) VALUES (
  ${quote(row.id)}, ${quote(row.name)}, ${quote(row.country)}, ${quote(row.officialUrl)},
  ${quote(JSON.stringify(row.programs || []))}, ${quote(row.sourceLabel)},
  ${quote(row.recordStatus)}, ${quote(row.storedReviewDate)}, CURRENT_TIMESTAMP
)
ON CONFLICT(id) DO UPDATE SET
  name=excluded.name,
  country=excluded.country,
  official_url=excluded.official_url,
  programs_json=excluded.programs_json,
  source_label=excluded.source_label,
  record_status=excluded.record_status,
  stored_review_date=excluded.stored_review_date,
  updated_at=CURRENT_TIMESTAMP;`);
}
lines.push('COMMIT;', '');

const output = path.join(root, 'migrations', '0002_seed_path_v78.sql');
fs.writeFileSync(output, lines.join('\n'));
console.log(`Wrote ${catalogue.records.length} university records to ${output}`);
